# Envoyer immédiatement l'email d'annonce portail
if records:
    valid_records = records.filtered(lambda r: r.email)

    if not valid_records:
        action = {'type': 'ir.actions.client', 'tag': 'display_notification', 'params': {'title': 'Attention', 'message': 'Aucun contact avec email.', 'type': 'warning', 'sticky': False}}
    else:
        template = env.ref('lolirine_email_templates.email_template_annonce_portail_partner', raise_if_not_found=False)
        if template:
            sent_count = 0
            error_count = 0
            for record in valid_records:
                try:
                    template.send_mail(record.id, force_send=True)
                    sent_count += 1
                except Exception as e:
                    error_count += 1

            skipped = len(records) - len(valid_records)

            if error_count > 0:
                message = f'{sent_count} envoyé(s), {error_count} erreur(s)'
                if skipped > 0:
                    message += f', {skipped} ignoré(s) (sans email)'
                notif_type = 'warning'
            else:
                message = f'{sent_count} email(s) envoyé(s) avec succès !'
                if skipped > 0:
                    message += f' ({skipped} ignoré(s) sans email)'
                notif_type = 'success'

            action = {
                'type': 'ir.actions.client',
                'tag': 'display_notification',
                'params': {
                    'title': 'Envoi terminé',
                    'message': message,
                    'type': notif_type,
                    'sticky': False,
                }
            }
        else:
            action = {'type': 'ir.actions.client', 'tag': 'display_notification', 'params': {'title': 'Erreur', 'message': 'Template non trouvé.', 'type': 'danger', 'sticky': True}}
else:
    action = {'type': 'ir.actions.client', 'tag': 'display_notification', 'params': {'title': 'Attention', 'message': 'Sélectionnez au moins un contact.', 'type': 'warning', 'sticky': False}}
